import { CurrencyPipe, DatePipe, UpperCasePipe } from '@angular/common';

@Component({
  selector: 'app-detalle-tarea',
  imports: [DatePipe, CurrencyPipe, UpperCasePipe],
  template: `
    <h2>{{ tarea().titulo | uppercase }}</h2>
    <p>Vence: {{ tarea().vence | date: 'dd/MM/yyyy' }}</p>
    <p>Presupuesto: {{ tarea().costo | currency: 'ARS' : 'symbol-narrow' }}</p>
  `,
})

import { Pipe, PipeTransform } from '@angular/core';

@Pipe({ name: 'iniciales' })
export class InicialesPipe implements PipeTransform {
  transform(nombre: string): string {
    return nombre.split(' ').map(p => p[0]).join('').toUpperCase();
  }
}
// uso: {{ 'Ana Gómez' | iniciales }}  ->  AG

