import { Pipe, PipeTransform } from '@angular/core';

@Pipe({ name: 'iniciales' })
export class InicialesPipe implements PipeTransform {
  transform(nombre: string): string {
    return nombre
      .split(' ')
      .map((p) => p[0])
      .join('')
      .toUpperCase();
  }
}

