import { DatePipe } from '@angular/common';
import { Component } from '@angular/core';
import { InicialesPipe } from './iniciales-pipe';

@Component({
  selector: 'app-root',
  imports: [DatePipe, InicialesPipe],
  template: `
    <h1>{{ tarea.titulo }}</h1>
    <p>Responsable: {{ tarea.responsable | iniciales }}</p>
    <p>Vence: {{ tarea.vence | date: 'dd/MM/yyyy' }}</p>
  `,
})
export class App {
